#!/usr/bin/env python3
"""Generate euler011-largest-product-grid.hla64 with embedded 20x20 grid."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
data = root / "examples/20-project-euler/data/euler011-matrix.txt"
out = root / "examples/20-project-euler/problems/euler011-largest-product-grid.hla64"

vals: list[int] = []
for line in data.read_text().splitlines():
    line = line.strip()
    if line:
        vals.extend(int(x) for x in line.split())
assert len(vals) == 400

lines = [
    "// euler011-largest-product-grid.hla64 — PE #11 (70600674)",
    "// Generated by scripts/generate_euler011.py",
    "",
    "program euler011;",
    "",
    '#include("stdlib64.hhf")',
    "",
    "static",
    "    grid: int64[400];",
    "endstatic;",
    "",
    "begin euler011;",
]
for i, v in enumerate(vals):
    lines.append(f"    mov({v}, grid[{i}]);")

